const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Death Valley National Park geometry (approximate center and bounds)
  const deathValley = ee.Geometry.Rectangle([-117.5, 35.9, -116.4, 37.0]);

  // 2. Define dates
  const julyDate = '2022-07-11';
  const augDate = '2022-08-07';

  // 3. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 4. Function to get water extent
  function getWaterExtent(date, dateLabel) {
    const col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(deathValley)
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .map(maskS2clouds);

    const size = col.size().getInfo();
    console.log(`${dateLabel} images found: ${size}`);

    if (size === 0) {
      // Try Landsat 8/9 as fallback
      const colL = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
        .filterBounds(deathValley)
        .filterDate(date, ee.Date(date).advance(1, 'day'));

      const sizeL = colL.size().getInfo();
      console.log(`${dateLabel} Landsat fallback images: ${sizeL}`);

      if (sizeL === 0) {
        return null;
      }

      const imgL = colL.first();
      const ndwiL = imgL.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
      const waterL = ndwiL.gt(0);

      const statsL = waterL.reduceRegion({
        reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
        geometry: deathValley,
        scale: 3000,
        maxPixels: 1e9
      });

      return {
        waterPixels: statsL.get('NDWI_sum').getInfo(),
        totalPixels: statsL.get('NDWI_count').getInfo()
      };
    }

    const img = col.first();
    const ndwi = img.normalizedDifference(['B3', 'B8']).rename('NDWI');
    const water = ndwi.gt(0);

    const stats = water.reduceRegion({
      reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
      geometry: deathValley,
      scale: 3000,
      maxPixels: 1e9
    });

    return {
      waterPixels: stats.get('NDWI_sum').getInfo(),
      totalPixels: stats.get('NDWI_count').getInfo()
    };
  }

  // 5. Get water extent for both dates
  const julyStats = getWaterExtent(julyDate, 'July');
  if (julyStats === null) {
    console.log('No data for July 11, 2022');
    console.log('<answer>C1</answer>');
    return;
  }

  const augStats = getWaterExtent(augDate, 'August');
  if (augStats === null) {
    console.log('No data for August 7, 2022');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Check for valid pixels
  if (julyStats.totalPixels === 0 || augStats.totalPixels === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Check for calculation failures
  if (julyStats.waterPixels === null || augStats.waterPixels === null || 
      isNaN(julyStats.waterPixels) || isNaN(augStats.waterPixels)) {
    console.log('Calculation failed - invalid values');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Output results
  console.log(`July 11: Water pixels = ${julyStats.waterPixels}, Total = ${julyStats.totalPixels}`);
  console.log(`August 7: Water pixels = ${augStats.waterPixels}, Total = ${augStats.totalPixels}`);

  // 9. Compare and answer
  if (augStats.waterPixels > julyStats.waterPixels) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
